// Get the input string from the first item
const inputString = $input.first().json.Section

// Split by newline and process each line
const cleanedArray = inputString.split('\n')
  .map(line => {
    // Remove the timestamp (00:00 or 00:00:00) and any leading space
    return line.replace(/^\d{2}:\d{2}(:\d{2})?\s*/, '').trim();
  })
  // Skip the first index ("Time Stamp")
  .slice(1)
  // Ensure no empty strings are included
  .filter(line => line.length > 0);

// Return as a single object containing the array
return {
  title:$input.first().json.Title,
  sections: cleanedArray
};

